using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;
public static class CityMobileOptimizationMeasure {
public static void Write(Scene scene,string path){var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).Where(r=>r.enabled&&r.gameObject.activeInHierarchy).ToArray();var groups=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<LODGroup>(true)).Where(g=>g.enabled&&g.gameObject.activeInHierarchy).ToArray();var controlled=new HashSet<Renderer>(groups.SelectMany(g=>g.GetLODs().SelectMany(l=>l.renderers)).Where(r=>r));var s=new StringBuilder("view,frustum_plus_LOD_renderers,frustum_plus_LOD_triangles\n");Vector3[] positions={new Vector3(-62,32,230),new Vector3(-32,58,-351.9f),new Vector3(222,39,295),new Vector3(-390,33,-405),new Vector3(480,33,-310),new Vector3(-220,33,62),new Vector3(168,33,-50),new Vector3(670,33,200)};Vector3[] targets={new Vector3(-62,31,320),new Vector3(-115,36,-351.9f),new Vector3(222,31,255),new Vector3(-410,35,-480),new Vector3(480,31,-200),new Vector3(-220,31,170),new Vector3(168,31,70),new Vector3(670,31,310)};for(int v=0;v<positions.Length;v++){var go=new GameObject("Temporary Optimization Measurement Camera"){hideFlags=HideFlags.HideAndDontSave};var c=go.AddComponent<Camera>();c.enabled=false;c.fieldOfView=62;c.aspect=1.4f;c.nearClipPlane=.1f;c.farClipPlane=2500;c.transform.SetPositionAndRotation(positions[v],Quaternion.LookRotation(targets[v]-positions[v]));var planes=GeometryUtility.CalculateFrustumPlanes(c);var selected=new HashSet<Renderer>(all.Where(r=>!controlled.Contains(r)));foreach(var g in groups){float distance=Vector3.Distance(c.transform.position,g.transform.TransformPoint(g.localReferencePoint));var scale=g.transform.lossyScale;float size=g.size*Mathf.Max(Mathf.Abs(scale.x),Mathf.Abs(scale.y),Mathf.Abs(scale.z));float relative=size*Mathf.Max(.001f,QualitySettings.lodBias)/(2*Mathf.Max(.001f,distance)*Mathf.Tan(c.fieldOfView*.5f*Mathf.Deg2Rad));foreach(var level in g.GetLODs())if(relative>=level.screenRelativeTransitionHeight){foreach(var r in level.renderers)if(r&&r.enabled&&r.gameObject.activeInHierarchy)selected.Add(r);break;}}long triangles=0;int visible=0;foreach(var r in selected){if(!GeometryUtility.TestPlanesAABB(planes,r.bounds))continue;var mf=r.GetComponent<MeshFilter>();if(!mf||!mf.sharedMesh)continue;visible++;triangles+=CityMobileMeshReducer.Triangles(mf.sharedMesh);}s.AppendLine(v+","+visible+","+triangles);UnityEngine.Object.DestroyImmediate(go);}File.WriteAllText(path,s.ToString());}
}
